69:   Future<void> _loadNextPage() async {
70:     if (_isLoadingMore || !_hasMore) return;
71: 
72:     final currencyRepository = context.read<CurrencyRepository>();
73: 
74:     setState(() => _isLoadingMore = true);
75: 
76:     try {
77:       final CurrencyPage page = await currencyRepository.fetchRates(
78:         CurrencyPageRequest(base: 'USD', page: _currentPage + 1),
79:       );
80: 
81:       _allCurrencies = [..._allCurrencies, ...page.items];
82:       _currentPage = page.page;
83:       _hasMore = page.hasMore;
84: 
85:       _applyFilter(_query);
86: 
87:       // сохраняем только элементы новой страницы
88:       await currencyRepository.saveCurrencyList(page.items);
89:     } finally {
90:       if (mounted) {
91:         setState(() => _isLoadingMore = false);
92:       }
93:     }
94:   }
