101:   void _applyFilter(String query) {
102:     final String lowerQuery = query.toLowerCase();
103:     final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
104:       return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
105:     });
106: 
107:     _filteredCurrenciesNotifier.value = result.toList(growable: false);
108:   }
